package ug.audiocity.studio;
import org.json.*;import java.io.*;import java.util.*;
/** Project (session.json) format: core fields plus routing, inserts, automation, takes, buses, markers, tempo map and templates. Platform independent apart from android.util.AtomicFile. */
public final class ProjectIO {
 private ProjectIO(){}
 public interface Opener{Core.Source open(File f)throws IOException;}
 static JSONObject fx(Core.Fx f)throws JSONException{JSONObject j=new JSONObject();j.put("hpf",f.hpf).put("peakGuard",f.peakGuard).put("inputDb",f.inputDb).put("outputDb",f.outputDb).put("highPassHz",f.highPassHz).put("midHz",f.midHz).put("gateFloor",f.gateFloor);if(f.wet)j.put("wet",true);j.put("delaySync",f.delaySync).put("pingPong",f.pingPong).put("leftBeats",f.leftBeats).put("rightBeats",f.rightBeats).put("leftMs",f.leftMs).put("rightMs",f.rightMs).put("delayFeedback",f.delayFeedback).put("delayWidth",f.delayWidth);j.put("eq",f.eq).put("gate",f.gate).put("comp",f.comp).put("deess",f.deess).put("sat",f.sat).put("delay",f.delay).put("room",f.room);j.put("low",f.low).put("mid",f.mid).put("high",f.high).put("gateDb",f.gateDb).put("threshold",f.threshold).put("ratio",f.ratio).put("deessAmount",f.deessAmount).put("drive",f.drive).put("delayMix",f.delayMix).put("roomMix",f.roomMix);return j;}
 static Core.Fx readFx(JSONObject j){Core.Fx f=new Core.Fx();if(j==null)return f;f.hpf=j.optBoolean("hpf",false);f.peakGuard=j.optBoolean("peakGuard",false);f.inputDb=clamp(j.optDouble("inputDb",0),-12,12);f.outputDb=clamp(j.optDouble("outputDb",0),-12,12);f.highPassHz=clamp(j.optDouble("highPassHz",90),40,180);f.midHz=clamp(j.optDouble("midHz",1200),250,2500);f.gateFloor=clamp(j.optDouble("gateFloor",0),0,1);f.wet=j.optBoolean("wet",false);f.delaySync=j.optBoolean("delaySync",true);f.pingPong=j.optBoolean("pingPong",false);f.leftBeats=clamp(j.optDouble("leftBeats",.5),.125,2);f.rightBeats=clamp(j.optDouble("rightBeats",.5),.125,2);f.leftMs=clamp(j.optDouble("leftMs",300),10,2000);f.rightMs=clamp(j.optDouble("rightMs",300),10,2000);f.delayFeedback=clamp(j.optDouble("delayFeedback",.35),0,.85);f.delayWidth=clamp(j.optDouble("delayWidth",1),0,1);f.eq=j.optBoolean("eq",true);f.gate=j.optBoolean("gate");f.comp=j.optBoolean("comp");f.deess=j.optBoolean("deess");f.sat=j.optBoolean("sat");f.delay=j.optBoolean("delay");f.room=j.optBoolean("room");f.low=clamp(j.optDouble("low",0),-12,12);f.mid=clamp(j.optDouble("mid",0),-12,12);f.high=clamp(j.optDouble("high",0),-12,12);f.gateDb=clamp(j.optDouble("gateDb",-50),-80,-20);f.threshold=clamp(j.optDouble("threshold",-18),-48,0);f.ratio=clamp(j.optDouble("ratio",3),1,10);f.deessAmount=clamp(j.optDouble("deessAmount",.4),0,1);f.drive=clamp(j.optDouble("drive",2),1,6);f.delayMix=clamp(j.optDouble("delayMix",.15),0,.6);f.roomMix=clamp(j.optDouble("roomMix",.18),0,.6);return f;}
 static double clamp(double n,double a,double b){return Double.isFinite(n)?Math.max(a,Math.min(b,n)):a;}
 public static synchronized void save(Core.Session s)throws Exception {JSONObject j=new JSONObject();j.put("schema",1).put("title",s.title).put("bpm",s.bpm).put("master",s.master).put("snapDivision",s.snapDivision).put("tuneKey",s.tuneKey).put("tuneScale",s.tuneScale).put("tuneSpeed",s.tuneSpeed).put("tuneRange",s.tuneRange).put("tuneStrength",s.tuneStrength).put("tuneConfigured",s.tuneConfigured);JSONArray tracks=new JSONArray();for(Core.Track t:s.tracks){if(t.ephemeral)continue;JSONObject tj=new JSONObject().put("id",t.id).put("name",t.name).put("color",t.color).put("volume",t.volume).put("pan",t.pan).put("mute",t.mute).put("solo",t.solo).put("bypassFx",t.bypassFx).put("fx",fx(t.fx));JSONArray clips=new JSONArray();for(Core.Clip c:t.clips)clips.put(clip(c));tj.put("clips",clips);writeTrack(t,tj);tracks.put(tj);}j.put("tracks",tracks);writeSession(s,j);byte[] encoded=j.toString().getBytes("UTF-8");if(encoded.length>1048576)throw new IOException("This project has too many clips or notes to save. Reduce it or split it into separate projects; the previous saved version was kept.");File dir=new File(s.directory);android.util.AtomicFile atomic=new android.util.AtomicFile(new File(dir,"session.json"));FileOutputStream stream=atomic.startWrite();try{stream.write(encoded);atomic.finishWrite(stream);}catch(Exception e){atomic.failWrite(stream);throw e;}}
 public static Core.Session load(File dir,Opener opener)throws Exception {byte[] bytes=new android.util.AtomicFile(new File(dir,"session.json")).readFully();if(bytes.length>1024*1024)throw new IOException("Session metadata is too large.");JSONObject j=new JSONObject(new String(bytes,"UTF-8"));if(j.optInt("schema")!=1)throw new IOException("Unsupported project version.");Core.Session s=new Core.Session();s.directory=dir.getAbsolutePath();s.title=j.optString("title","Untitled session");s.bpm=(int)clamp(j.optInt("bpm",100),40,240);s.master=clamp(j.optDouble("master",.85),0,2);s.tuneKey=(int)clamp(j.optInt("tuneKey",0),0,11);s.tuneScale=(int)clamp(j.optInt("tuneScale",0),0,2);s.tuneSpeed=(int)clamp(j.optInt("tuneSpeed",0),0,3);s.tuneRange=(int)clamp(j.optInt("tuneRange",0),0,2);s.tuneStrength=clamp(j.optDouble("tuneStrength",1),0,1);s.tuneConfigured=j.optBoolean("tuneConfigured",false);s.snapDivision=j.optInt("snapDivision",4);if(!java.util.Arrays.asList(0,1,2,4,8,16,-1,-2).contains(s.snapDivision))s.snapDivision=4;JSONArray ts=j.getJSONArray("tracks");if(ts.length()>Core.MAX_TRACKS)throw new IOException("Too many tracks.");Map<String,Core.Source> sources=new HashMap<>();for(int i=0;i<ts.length();i++){JSONObject a=ts.getJSONObject(i);Core.Track t=new Core.Track(a.getString("name"),a.getInt("color"));t.id=a.getString("id");t.volume=clamp(a.optDouble("volume",.8),0,2);t.pan=clamp(a.optDouble("pan",0),-1,1);t.mute=a.optBoolean("mute");t.solo=a.optBoolean("solo");t.bypassFx=a.optBoolean("bypassFx");t.fx=readFx(a.optJSONObject("fx"));JSONArray cs=a.getJSONArray("clips");for(int k=0;k<cs.length();k++){Core.Clip clip=readClip(cs.getJSONObject(k),dir,sources,opener);t.clips.add(clip);}readTrack(a,t,dir,sources,opener);s.tracks.add(t);}readSession(j,s,dir,sources,opener);return s;}
 static JSONObject clip(Core.Clip c)throws JSONException{JSONObject j=clipCore(c);if(c.notes!=null&&c.drumPattern==null){JSONArray n=new JSONArray();for(Pro.Note x:c.notes)n.put(new JSONArray().put(x.start).put(x.length).put(x.pitch).put(x.velocity).put(x.channel));j.put("notes",n).put("instrument",instrument(c.instrument));if(c.instrumentPackId!=null)j.put("instrumentPack",c.instrumentPackId);if(c.instrumentFile!=null)j.put("instrumentData",c.instrumentFile);}if(c.drumPattern!=null)j.put("drumPattern",c.drumPattern);if(c.patternId!=null)j.put("patternId",c.patternId).put("patternLane",c.patternLane);if(c.stretchFile!=null)j.put("stretchFile",c.stretchFile).put("stretchOffset",c.stretchOffset).put("stretchLength",c.stretchLength).put("stretchRatio",c.stretchRatio);if(c.vocalNotes!=null)j.put("vocalNotes",ProVocal.toJson(c.vocalNotes)).put("vocalOffset",c.vocalOffset).put("vocalLength",c.vocalLength);return j;}
 static JSONObject clipCore(Core.Clip c)throws JSONException{return new JSONObject().put("name",c.name).put("file",c.file).put("midiFile",c.midiFile).put("tuneSourceFile",c.tuneSourceFile).put("tuneSourceOffset",c.tuneSourceOffset).put("start",c.start).put("offset",c.offset).put("length",c.length).put("gain",c.gain).put("fadeIn",c.fadeIn).put("fadeOut",c.fadeOut).put("envelopeOffset",c.envelopeOffset).put("envelopeLength",c.envelopeLength);}
 static boolean validBeatPilotPattern(String text){try{BeatPilotDrumRollData.decode(text);return true;}catch(RuntimeException e){return false;}}
 static Core.Clip readClip(JSONObject c,File dir,Map<String,Core.Source> sources,Opener opener)throws Exception{if(c.has("notes"))return readMidiClip(c);Core.Clip clip=readAudioClip(c,dir,sources,opener);String pattern=id(c.optString("patternId",""));int lane=c.optInt("patternLane",-1);if(pattern!=null&&lane>=0&&lane<8){clip.patternId=pattern;clip.patternLane=lane;}String dp=c.optString("drumPattern","");if(!dp.isEmpty()&&dp.length()<=131072&&validBeatPilotPattern(dp)){clip.drumPattern=dp;clip.notes=BeatPilotDrumRollData.decode(dp).notes();}String sf=c.optString("stretchFile","");if(!sf.isEmpty()&&!sf.equals("null")){File p=new File(dir,sf);if(!p.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException("Invalid original clip path.");Core.Source o=sources.get(sf);if(o==null){o=opener.open(p);sources.put(sf,o);}int so=c.optInt("stretchOffset",0),sl=c.optInt("stretchLength",0);if(so>=0&&sl>0&&so+(long)sl<=o.frames()){clip.stretchFile=sf;clip.stretchOffset=so;clip.stretchLength=sl;clip.stretchRatio=clamp(c.optDouble("stretchRatio",1),.25,4);}}JSONArray vn=c.optJSONArray("vocalNotes");if(vn!=null){clip.vocalNotes=ProVocal.fromJson(vn);clip.vocalOffset=c.optInt("vocalOffset",0);clip.vocalLength=c.optInt("vocalLength",0);}return clip;}
 static Core.Clip readAudioClip(JSONObject c,File dir,Map<String,Core.Source> sources,Opener opener)throws Exception{String file=c.getString("file");File audio=new File(dir,file);if(!audio.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException("Invalid project audio path.");Core.Source source=sources.get(file);if(source==null){source=opener.open(audio);sources.put(file,source);}Core.Clip clip=new Core.Clip(c.getString("name"),source,file,c.getLong("start"));clip.offset=c.getInt("offset");clip.length=c.getInt("length");String midi=c.optString("midiFile","");if(!midi.isEmpty()&&!midi.equals("null")){File midiPath=new File(dir,midi);if(!midiPath.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile())||!midi.endsWith(".mid"))throw new IOException("Invalid MIDI source path");clip.midiFile=midi;}String originalFile=c.optString("tuneSourceFile","");if(!originalFile.isEmpty()&&!originalFile.equals("null")){File originalPath=new File(dir,originalFile);if(!originalPath.getCanonicalFile().getParentFile().equals(dir.getCanonicalFile()))throw new IOException("Invalid original vocal path.");Core.Source original=sources.get(originalFile);if(original==null){original=opener.open(originalPath);sources.put(originalFile,original);}clip.tuneSourceFile=originalFile;clip.tuneSourceOffset=c.optInt("tuneSourceOffset",0);if(clip.tuneSourceOffset<0||clip.tuneSourceOffset+(long)clip.offset+clip.length>original.frames())throw new IOException("Invalid original vocal boundaries.");}clip.gain=clamp(c.optDouble("gain",1),Math.pow(10,-24.0/20),Math.pow(10,24.0/20));clip.fadeIn=c.optInt("fadeIn",0);clip.fadeOut=c.optInt("fadeOut",0);clip.envelopeOffset=c.optInt("envelopeOffset",0);clip.envelopeLength=c.optInt("envelopeLength",clip.length);if(clip.fadeIn<0||clip.fadeOut<0||clip.envelopeOffset<0||clip.envelopeLength<clip.length||clip.envelopeLength>Core.MAX_FRAMES||clip.envelopeOffset+(long)clip.length>clip.envelopeLength||clip.fadeIn>clip.envelopeLength||clip.fadeOut>clip.envelopeLength)throw new IOException("Invalid clip fade boundaries.");if(clip.start<0||clip.offset<0||clip.length<1||clip.offset+(long)clip.length>source.frames()||clip.start+clip.length>Core.MAX_FRAMES)throw new IOException("Invalid clip boundaries.");return clip;}

 // ---------------------------------------------------------------- professional-feature extensions (all optional in the file)
 static final int MAX_POINTS=20000,MAX_TAKES=64,MAX_INSERTS=12,MAX_SENDS=8,MAX_MARKERS=500;

 static JSONObject insert(Pro.Insert i)throws JSONException{JSONArray v=new JSONArray();for(double d:i.values)v.put(d);return new JSONObject().put("id",i.id).put("kind",i.kind).put("enabled",i.enabled).put("values",v);}
 static Pro.Insert readInsert(JSONObject j){if(j==null||!Pro.KINDS.containsKey(j.optString("kind")))return null;JSONArray v=j.optJSONArray("values");double[] values=new double[v==null?0:Math.min(v.length(),256)];for(int i=0;i<values.length;i++)values[i]=v.optDouble(i,Double.NaN);Pro.Kind k=Pro.KINDS.get(j.optString("kind"));for(int i=0;i<values.length&&i<k.defaults.length;i++)if(!Double.isFinite(values[i]))values[i]=k.defaults[i];String id=j.optString("id","");if(id.isEmpty()||id.length()>64)id=UUID.randomUUID().toString();Pro.Insert ins=new Pro.Insert(id,k.id,values);ins.enabled=j.optBoolean("enabled",true);return ins;}
 static JSONArray inserts(List<Pro.Insert> list)throws JSONException{JSONArray a=new JSONArray();for(Pro.Insert i:list)a.put(insert(i));return a;}
 static void readInserts(JSONArray a,List<Pro.Insert> into){into.clear();if(a==null)return;for(int i=0;i<a.length()&&into.size()<MAX_INSERTS;i++){Pro.Insert ins=readInsert(a.optJSONObject(i));if(ins!=null)into.add(ins);}}
 static JSONObject lane(Pro.Lane l)throws JSONException{JSONArray f=new JSONArray(),v=new JSONArray();for(int i=0;i<l.size();i++){f.put(l.frame(i));v.put(l.value(i));}return new JSONObject().put("param",l.param).put("enabled",l.enabled).put("frames",f).put("values",v);}
 static Pro.Lane readLane(JSONObject j){if(j==null)return null;String p=j.optString("param","");if(!validParam(p))return null;JSONArray f=j.optJSONArray("frames"),v=j.optJSONArray("values");if(f==null||v==null)return null;int n=Math.min(MAX_POINTS,Math.min(f.length(),v.length()));long[] fr=new long[n];double[] va=new double[n];int k=0;for(int i=0;i<n;i++){long at=f.optLong(i,-1);double x=v.optDouble(i,Double.NaN);if(at<0||at>Core.MAX_FRAMES||!Double.isFinite(x))continue;fr[k]=at;va[k++]=x;}Pro.Lane l=new Pro.Lane(p);l.set(Arrays.copyOf(fr,k),Arrays.copyOf(va,k));l.enabled=j.optBoolean("enabled",true);return l;}
 static boolean validParam(String p){if(p.startsWith("send:"))return p.length()<80;for(String a:Pro.AUTOMATABLE)if(a.equals(p))return true;return false;}

 static void writeTrack(Core.Track t,JSONObject tj)throws JSONException{
  if(t.output!=null)tj.put("output",t.output);if(t.group!=null)tj.put("group",t.group);if(t.folder!=null)tj.put("folder",t.folder);if(t.sidechain!=null)tj.put("sidechain",t.sidechain);if(t.autoCrossfade)tj.put("autoCrossfade",true);
  if(!t.sends.isEmpty()){JSONArray a=new JSONArray();for(Pro.Send x:t.sends)a.put(new JSONObject().put("bus",x.bus).put("level",x.level).put("pre",x.pre));tj.put("sends",a);}
  if(!t.inserts.isEmpty())tj.put("inserts",inserts(t.inserts));
  if(!t.automation.isEmpty()){JSONArray a=new JSONArray();for(Pro.Lane l:t.automation.values())a.put(lane(l));tj.put("automation",a);}
  if(!t.takes.isEmpty()){JSONArray a=new JSONArray();for(Core.Clip c:t.takes)a.put(clip(c));tj.put("takes",a);}
  boolean anySlot=false;for(Core.Clip c:t.slots)if(c!=null)anySlot=true;if(anySlot){JSONArray a=new JSONArray();for(Core.Clip c:t.slots)a.put(c==null?JSONObject.NULL:clip(c));tj.put("slots",a);}
 }
 static void readTrack(JSONObject a,Core.Track t,File dir,Map<String,Core.Source> sources,Opener opener)throws Exception{
  t.output=id(a.optString("output",""));t.group=text(a.optString("group",""),40);t.folder=text(a.optString("folder",""),40);t.sidechain=id(a.optString("sidechain",""));t.autoCrossfade=a.optBoolean("autoCrossfade",false);
  JSONArray s=a.optJSONArray("sends");if(s!=null)for(int i=0;i<s.length()&&t.sends.size()<MAX_SENDS;i++){JSONObject x=s.optJSONObject(i);if(x==null||id(x.optString("bus",""))==null)continue;t.sends.add(new Pro.Send(x.optString("bus"),clamp(x.optDouble("level",0),0,2),x.optBoolean("pre",false)));}
  readInserts(a.optJSONArray("inserts"),t.inserts);
  JSONArray au=a.optJSONArray("automation");if(au!=null)for(int i=0;i<au.length()&&i<64;i++){Pro.Lane l=readLane(au.optJSONObject(i));if(l!=null)t.automation.put(l.param,l);}
  JSONArray tk=a.optJSONArray("takes");if(tk!=null&&dir!=null)for(int i=0;i<tk.length()&&t.takes.size()<MAX_TAKES;i++)t.takes.add(readClip(tk.getJSONObject(i),dir,sources,opener));
  JSONArray sl=a.optJSONArray("slots");if(sl!=null&&dir!=null)for(int i=0;i<sl.length()&&i<ProLive.SLOTS;i++){JSONObject c=sl.optJSONObject(i);t.slots.add(c==null?null:readClip(c,dir,sources,opener));}
 }
 static String id(String s){return s==null||s.isEmpty()||s.equals("null")||s.length()>64?null:s;}
 static String text(String s,int max){if(s==null||s.isEmpty()||s.equals("null"))return null;return s.length()>max?s.substring(0,max):s;}

 static JSONObject bus(Core.Track b)throws JSONException{JSONObject j=new JSONObject().put("id",b.id).put("name",b.name).put("color",b.color).put("volume",b.volume).put("pan",b.pan).put("mute",b.mute).put("bypassFx",b.bypassFx).put("fx",fx(b.fx));if(!b.inserts.isEmpty())j.put("inserts",inserts(b.inserts));if(b.sidechain!=null)j.put("sidechain",b.sidechain);if(!b.automation.isEmpty()){JSONArray a=new JSONArray();for(Pro.Lane l:b.automation.values())a.put(lane(l));j.put("automation",a);}return j;}
 static Core.Track readBus(JSONObject j)throws Exception{Core.Track b=new Core.Track(text(j.optString("name","Bus"),40)==null?"Bus":text(j.optString("name","Bus"),40),j.optInt("color",0xffc9b06b));String id=id(j.optString("id",""));if(id!=null)b.id=id;b.bus=true;b.volume=clamp(j.optDouble("volume",.8),0,2);b.pan=clamp(j.optDouble("pan",0),-1,1);b.mute=j.optBoolean("mute");b.bypassFx=j.optBoolean("bypassFx");b.fx=readFx(j.optJSONObject("fx"));readInserts(j.optJSONArray("inserts"),b.inserts);b.sidechain=id(j.optString("sidechain",""));JSONArray au=j.optJSONArray("automation");if(au!=null)for(int i=0;i<au.length()&&i<64;i++){Pro.Lane l=readLane(au.optJSONObject(i));if(l!=null)b.automation.put(l.param,l);}return b;}

 static void writeSession(Core.Session s,JSONObject j)throws JSONException{
  if(!s.patterns.isEmpty()){JSONArray bank=new JSONArray();for(PatternLibrary.Entry entry:s.patterns)bank.put(new JSONObject().put("id",entry.id).put("name",entry.name).put("data",entry.data));j.put("beatPatterns",bank);}
  if(s.timeSignature!=4)j.put("timeSignature",s.timeSignature);if(s.snapRelative)j.put("snapRelative",true);if(!s.magnet)j.put("magnet",false);if(s.dragMode!=0)j.put("dragMode",s.dragMode);if(s.crossfadeFrames!=Pro.DEFAULT_CROSSFADE)j.put("crossfadeFrames",s.crossfadeFrames);
  if(!s.buses.isEmpty()){JSONArray a=new JSONArray();for(Core.Track b:s.buses)a.put(bus(b));j.put("buses",a);}
  if(!s.markers.isEmpty()){JSONArray a=new JSONArray();for(Pro.Marker m:s.markers)a.put(new JSONObject().put("frame",m.frame).put("name",m.name));j.put("markers",a);}
  if(!s.tempoChanges.isEmpty()){JSONArray a=new JSONArray();for(Pro.TempoChange c:s.tempoChanges)a.put(new JSONObject().put("bar",c.bar).put("bpm",c.bpm));j.put("tempoChanges",a);}
  if(!s.masterInserts.isEmpty())j.put("masterInserts",inserts(s.masterInserts));
  if(s.masterAutomation!=null)j.put("masterAutomation",lane(s.masterAutomation));
  if(!s.collapsed.isEmpty()){JSONArray a=new JSONArray();for(String f:s.collapsed)a.put(f);j.put("collapsedFolders",a);}
  if(s.loopEnd>s.loopStart)j.put("loopStart",s.loopStart).put("loopEnd",s.loopEnd);if(s.notes!=null&&!s.notes.isEmpty())j.put("notes",s.notes.length()>20000?s.notes.substring(0,20000):s.notes);
  if(s.reference!=null&&s.directory!=null)j.put("reference",clip(s.reference)).put("referenceGain",s.referenceGain);
  if(!s.midiMap.isEmpty()){JSONArray a=new JSONArray();for(ProLive.Mapping m:s.midiMap)a.put(new JSONObject().put("channel",m.channel).put("number",m.number).put("note",m.note).put("target",m.target));j.put("midiMap",a);}
 }
 static void readSession(JSONObject j,Core.Session s,File dir,Map<String,Core.Source> sources,Opener opener)throws Exception{
  JSONArray bank=j.optJSONArray("beatPatterns");if(bank!=null)for(int i=0;i<bank.length()&&s.patterns.size()<PatternLibrary.MAX_PATTERNS;i++){JSONObject item=bank.optJSONObject(i);if(item==null)continue;String key=id(item.optString("id",""));if(key==null||PatternLibrary.find(s,key)!=null)continue;try{s.patterns.add(new PatternLibrary.Entry(key,item.optString("name","Pattern"),item.optString("data","")));}catch(IllegalArgumentException invalid){}}
  s.snapRelative=j.optBoolean("snapRelative",false);s.magnet=j.optBoolean("magnet",true);int dm=j.optInt("dragMode",0);s.dragMode=dm>=0&&dm<=3?dm:0;int sig=j.optInt("timeSignature",4);s.timeSignature=sig>=2&&sig<=12?sig:4;s.crossfadeFrames=(int)clamp(j.optInt("crossfadeFrames",Pro.DEFAULT_CROSSFADE),48,Core.RATE);
  JSONArray b=j.optJSONArray("buses");if(b!=null)for(int i=0;i<b.length()&&s.buses.size()<Core.MAX_BUSES;i++){JSONObject x=b.optJSONObject(i);if(x!=null)s.buses.add(readBus(x));}
  JSONArray m=j.optJSONArray("markers");if(m!=null)for(int i=0;i<m.length()&&s.markers.size()<MAX_MARKERS;i++){JSONObject x=m.optJSONObject(i);if(x==null)continue;long f=x.optLong("frame",-1);if(f<0||f>Core.MAX_FRAMES)continue;String name=text(x.optString("name",""),40);s.markers.add(new Pro.Marker(f,name==null?"Marker":name));}
  JSONArray tc=j.optJSONArray("tempoChanges");if(tc!=null)for(int i=0;i<tc.length()&&i<256;i++){JSONObject x=tc.optJSONObject(i);if(x==null)continue;int bar=x.optInt("bar",0),bpm=x.optInt("bpm",0);if(bar>=1&&bar<=10000&&bpm>=40&&bpm<=240)s.tempoChanges.add(new Pro.TempoChange(bar,bpm));}
  long ls=j.optLong("loopStart",0),le=j.optLong("loopEnd",0);if(ls>=0&&le>ls&&le<=Core.MAX_FRAMES){s.loopStart=ls;s.loopEnd=le;}String notes=j.optString("notes","");s.notes=notes.equals("null")?"":notes.length()>20000?notes.substring(0,20000):notes;JSONObject ref=j.optJSONObject("reference");if(ref!=null&&dir!=null){s.reference=readClip(ref,dir,sources,opener);s.referenceGain=clamp(j.optDouble("referenceGain",1),Pro.gain(-40),Pro.gain(40));}JSONArray mm=j.optJSONArray("midiMap");if(mm!=null)for(int i=0;i<mm.length()&&i<256;i++){JSONObject x=mm.optJSONObject(i);if(x==null)continue;int ch=x.optInt("channel",-1),num=x.optInt("number",-1);String tg=text(x.optString("target",""),120);if(ch<-1||ch>15||num<0||num>127||tg==null||!tg.matches("(transport|master|track):[A-Za-z0-9:_.-]+"))continue;s.midiMap.add(new ProLive.Mapping(ch,num,x.optBoolean("note",false),tg));}readInserts(j.optJSONArray("masterInserts"),s.masterInserts);JSONArray cf=j.optJSONArray("collapsedFolders");if(cf!=null)for(int i=0;i<cf.length()&&i<64;i++){String f=text(cf.optString(i),40);if(f!=null)s.collapsed.add(f);}
  JSONObject ma=j.optJSONObject("masterAutomation");if(ma!=null){Pro.Lane l=readLane(ma);if(l!=null&&l.param.equals("volume"))s.masterAutomation=l;}
  // drop references to buses or tracks that no longer exist
  for(Core.Track t:s.tracks){if(t.output!=null&&s.bus(t.output)==null)t.output=null;if(t.sidechain!=null&&s.track(t.sidechain)==null)t.sidechain=null;t.sends.removeIf(x->s.bus(x.bus)==null);}
  for(Core.Track t:s.buses)if(t.sidechain!=null&&s.track(t.sidechain)==null)t.sidechain=null;
 }

 /** Every audio file a project references, including takes (for backups). */
 public static LinkedHashSet<String> files(Core.Session s){
  LinkedHashSet<String> names=new LinkedHashSet<>();names.addAll(UserDrumPacks.projectFiles(s));if(AfroDrumPack.used(s))names.add(AfroDrumPack.FILE);if(s.reference!=null)addFiles(names,s.reference);
  for(Core.Track t:s.tracks){if(t.ephemeral)continue;for(Core.Clip c:t.clips)addFiles(names,c);for(Core.Clip c:t.takes)addFiles(names,c);for(Core.Clip c:t.slots)if(c!=null)addFiles(names,c);}
  return names;
 }
 private static void addFiles(Set<String> names,Core.Clip c){for(String file:new String[]{c.file,c.stretchFile,c.tuneSourceFile,c.midiFile,c.instrumentFile})if(file!=null&&!file.isEmpty())names.add(file);}


 // ---------------------------------------------------------------- templates and track presets

 /** Serialises a session's structure without any audio: tracks, buses, routing, FX, inserts, tempo and time signature. */
 public static String template(Core.Session s)throws JSONException{JSONObject j=new JSONObject().put("schema",1).put("kind","template").put("title",s.title).put("bpm",s.bpm).put("master",s.master).put("snapDivision",s.snapDivision);JSONArray tracks=new JSONArray();for(Core.Track t:s.tracks){if(t.ephemeral)continue;JSONObject tj=new JSONObject().put("id",t.id).put("name",t.name).put("color",t.color).put("volume",t.volume).put("pan",t.pan).put("bypassFx",t.bypassFx).put("fx",fx(t.fx));if(t.output!=null)tj.put("output",t.output);if(t.group!=null)tj.put("group",t.group);if(t.folder!=null)tj.put("folder",t.folder);if(t.sidechain!=null)tj.put("sidechain",t.sidechain);if(!t.sends.isEmpty()){JSONArray a=new JSONArray();for(Pro.Send x:t.sends)a.put(new JSONObject().put("bus",x.bus).put("level",x.level).put("pre",x.pre));tj.put("sends",a);}if(!t.inserts.isEmpty())tj.put("inserts",inserts(t.inserts));tracks.put(tj);}j.put("tracks",tracks);Core.Session shell=new Core.Session();shell.patterns.addAll(s.patterns);shell.timeSignature=s.timeSignature;shell.tempoChanges.addAll(s.tempoChanges);shell.buses.addAll(s.buses);shell.masterInserts.addAll(s.masterInserts);writeSession(shell,j);return j.toString();}
 /** Builds a new empty project from a template. Track and bus ids are regenerated so templates can be reused. */
 public static Core.Session fromTemplate(String json,String directory)throws Exception{JSONObject j=new JSONObject(json);if(!"template".equals(j.optString("kind")))throw new IOException("This file is not a project template.");Core.Session s=new Core.Session();s.directory=directory;s.title=text(j.optString("title","Untitled session"),60);if(s.title==null)s.title="Untitled session";s.bpm=(int)clamp(j.optInt("bpm",100),40,240);s.master=clamp(j.optDouble("master",.85),0,2);s.snapDivision=j.optInt("snapDivision",4);if(!Arrays.asList(0,1,2,4,8,16,-1,-2).contains(s.snapDivision))s.snapDivision=4;JSONArray ts=j.optJSONArray("tracks");if(ts!=null)for(int i=0;i<ts.length()&&s.tracks.size()<Core.MAX_TRACKS;i++){JSONObject a=ts.getJSONObject(i);Core.Track t=new Core.Track(text(a.optString("name","Audio"),40)==null?"Audio":text(a.optString("name","Audio"),40),a.optInt("color",0xff50cfc9));String id=id(a.optString("id",""));if(id!=null)t.id=id;t.volume=clamp(a.optDouble("volume",.8),0,2);t.pan=clamp(a.optDouble("pan",0),-1,1);t.bypassFx=a.optBoolean("bypassFx");t.fx=readFx(a.optJSONObject("fx"));readTrack(a,t,null,null,null);s.tracks.add(t);}readSession(j,s,null,null,null);
  // fresh ids, keeping routing intact
  Map<String,String> ids=new HashMap<>();for(Core.Track t:s.tracks){String n=UUID.randomUUID().toString();ids.put(t.id,n);t.id=n;}for(Core.Track b:s.buses){String n=UUID.randomUUID().toString();ids.put(b.id,n);b.id=n;}
  for(Core.Track t:s.tracks){if(t.output!=null)t.output=ids.get(t.output);if(t.sidechain!=null)t.sidechain=ids.get(t.sidechain);ArrayList<Pro.Send> sends=new ArrayList<>();for(Pro.Send x:t.sends)if(ids.containsKey(x.bus))sends.add(new Pro.Send(ids.get(x.bus),x.level,x.pre));t.sends.clear();t.sends.addAll(sends);}
  for(Core.Track b:s.buses)if(b.sidechain!=null)b.sidechain=ids.get(b.sidechain);
  return s;}
 /** A channel preset: channel-strip FX plus insert chain. */
 public static String trackPreset(Core.Track t)throws JSONException{return new JSONObject().put("kind","trackPreset").put("fx",fx(t.fx)).put("inserts",inserts(t.inserts)).toString();}
 public static void applyTrackPreset(Core.Track t,String json)throws Exception{JSONObject j=new JSONObject(json);if(!"trackPreset".equals(j.optString("kind")))throw new IOException("This is not a channel preset.");t.fx=readFx(j.optJSONObject("fx"));ArrayList<Pro.Insert> list=new ArrayList<>();readInserts(j.optJSONArray("inserts"),list);for(int i=0;i<list.size();i++){Pro.Insert x=list.get(i);list.set(i,new Pro.Insert(UUID.randomUUID().toString(),x.kind,x.values));list.get(i).enabled=x.enabled;}t.inserts.clear();t.inserts.addAll(list);}

 /** After a tempo conversion: scales automation, markers and tempo changes by the speed factor (new bpm / old bpm). */
 public static void retimeExtras(Core.Session s,double speed){s.loopStart=Math.round(s.loopStart/speed);s.loopEnd=Math.round(s.loopEnd/speed);for(Core.Track t:s.tracks)scaleLanes(t,speed);for(Core.Track b:s.buses)scaleLanes(b,speed);if(s.masterAutomation!=null)scale(s.masterAutomation,speed);for(Pro.Marker m:s.markers)m.frame=Math.round(m.frame/speed);ArrayList<Pro.TempoChange> c=new ArrayList<>();for(Pro.TempoChange x:s.tempoChanges)c.add(new Pro.TempoChange(x.bar,(int)Math.round(clamp(x.bpm*speed,40,240))));s.tempoChanges.clear();s.tempoChanges.addAll(c);}
 static void scaleLanes(Core.Track t,double speed){for(Pro.Lane l:t.automation.values())scale(l,speed);}
 static void scale(Pro.Lane l,double speed){long[] f=new long[l.size()];double[] v=new double[l.size()];for(int i=0;i<f.length;i++){f[i]=Math.round(l.frame(i)/speed);v[i]=l.value(i);}l.set(f,v);}
 static JSONObject instrument(Synth.Config c)throws JSONException{return new JSONObject().put("patch",c.patch).put("attack",c.attack).put("decay",c.decay).put("sustain",c.sustain).put("release",c.release).put("tone",c.tone).put("detune",c.detune);}
 static Synth.Config readInstrument(JSONObject j){Synth.Config c=Synth.factory((int)clamp(j==null?3:j.optInt("patch",3),0,Synth.NAMES.length-1));if(j==null)return c;c.attack=clamp(j.optDouble("attack",c.attack),.0005,4);c.decay=clamp(j.optDouble("decay",c.decay),.005,8);c.sustain=clamp(j.optDouble("sustain",c.sustain),0,1);c.release=clamp(j.optDouble("release",c.release),.005,8);c.tone=clamp(j.optDouble("tone",c.tone),0,1);c.detune=clamp(j.optDouble("detune",c.detune),0,50);return c;}
 /** A live MIDI clip: notes + instrument, rendered on load (no audio file). */
 static Core.Clip readMidiClip(JSONObject c)throws Exception{JSONArray a=c.getJSONArray("notes");if(a.length()>ProMidi.MAX_NOTES)throw new IOException("Too many MIDI notes in a clip.");ArrayList<Pro.Note> notes=new ArrayList<>();for(int i=0;i<a.length();i++){JSONArray n=a.optJSONArray(i);if(n==null||n.length()<4)continue;long st=n.optLong(0,-1),len=n.optLong(1,0);int p=(int)n.optLong(2,-1),v=(int)n.optLong(3,0),ch=(int)n.optLong(4,0);if(st<0||len<1||st+len>Core.MAX_FRAMES||p<0||p>127||v<1||v>127||ch<0||ch>15)continue;notes.add(new Pro.Note(p,v,st,len,ch));}
  long at=c.optLong("start",0);int length=c.optInt("length",Core.RATE);if(at<0||length<1||at+length>Core.MAX_FRAMES)throw new IOException("Invalid MIDI clip boundaries.");Core.Clip clip=ProMidi.clip(text(c.optString("name","MIDI"),60)==null?"MIDI":text(c.optString("name","MIDI"),60),notes,readInstrument(c.optJSONObject("instrument")),at,c.optInt("offset",0)+length);String pack=c.optString("instrumentPack","");if(!pack.isEmpty()&&!pack.equals("null")&&pack.length()<=256)clip.instrumentPackId=pack;String embedded=c.optString("instrumentData","");if(embedded.endsWith(".acpack")&&!embedded.contains("/")&&!embedded.contains("\\"))clip.instrumentFile=embedded;
  int off=c.optInt("offset",0);if(off<0||off+(long)length>clip.source.frames())throw new IOException("Invalid MIDI clip boundaries.");clip.offset=off;clip.length=length;clip.gain=clamp(c.optDouble("gain",1),Pro.gain(-24),Pro.gain(24));clip.fadeIn=Math.max(0,c.optInt("fadeIn",0));clip.fadeOut=Math.max(0,c.optInt("fadeOut",0));clip.envelopeOffset=Math.max(0,c.optInt("envelopeOffset",0));clip.envelopeLength=Math.max(clip.envelopeOffset+length,c.optInt("envelopeLength",clip.source.frames()));return clip;}
}
